sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var hrGroup = '00a1366bc33bcb90150658e1b40131ec';
    var itGroup = '34c13eabc33bcb90150658e1b4013178';

    var map = {
        'hr': hrGroup,
        'payroll': hrGroup,
        'it': itGroup,
        'access': itGroup
    };

    g_form.setValue('assignment_group', map[newValue] || '');

	if(newValue == 'access') {
        g_form.setValue('priority', '2');
    }
}
